# -*- coding: utf-8 -*-
"""★ 文件类型图标的 base64 数据（2026-10-07 从 AIxiede.py 搬出来的）。

★★ 为什么搬出来：
   这些数据原来在主程序里占 **680 KB = 整个程序的 32%** ——
   比 `FileTaggerApp` 主类（381 KB）还大近一倍，
   是主程序"臃肿"的**最大一块**。
   搬出来之后主程序 2152 KB → **1472 KB（省 32%）**。

★★ 为什么这样搬是安全的（这是重点）：
   主程序里取图标的 `get_file_icon()` **本来就有**"取不到就返回 None"的路子，
   而**所有调用方都会退回 emoji 显示**
   （错题本 #5 那条：最坏情况要能看能点，不能一片空白）。
   所以：**本文件丢了/找不到 = 图标退回 emoji，程序照常开。**
   —— 跟"删掉兜底类"完全不是一回事（那个会让程序打不开）。

★ 内容：**从主程序原样搬过来的，一个字符都没改**。
   搬运时核对过 sha256：cbe95a3924a575d24db8

★ 想换图标：
   改 `_图标定稿\` 里的图 → 跑 `_图标打包.py` 生成 `_icons_embed.py`
   → 把其中 `ICON_PNG[...]` 那几段贴到本文件（或重跑 `_图标外置.py`）。
"""

ICON_SIZES = [64, 96, 128, 192, 256, 384]

